/* @autogenerated */
package net.civeira.phylax.testing.sql;

import java.io.ByteArrayInputStream;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.sql.DataSource;

/**
 * A tiny in memory database behind the jdbc interfaces, to unit test the generated repositories
 * without a real database.
 *
 * <p>
 * It understands the sql written by the repositories: insert with a column list, update with "set
 * col = ?" (and "col = col + 1"), delete, and select of columns or count from one table. The where
 * clauses are evaluated with the simple conditions (=, <>, >, <, >=, <=, like, in, is null) joined
 * with "and"; the conditions inside parentheses (pagination offsets) are ignored. The values are
 * stored as they are bound, so a mismatch between the columns written and read is detected.
 */
public class InMemoryJdbc {
  private static final Pattern INSERT = Pattern
      .compile("(?is)^\\s*insert\\s+into\\s+(\\S+)\\s*\\((.*?)\\)\\s*values\\s*\\((.*)\\)\\s*$");
  private static final Pattern UPDATE =
      Pattern.compile("(?is)^\\s*update\\s+(\\S+)\\s+set\\s+(.*?)(?:\\s+where\\s+(.*))?$");
  private static final Pattern DELETE =
      Pattern.compile("(?is)^\\s*delete\\s+from\\s+(\\S+)(?:\\s+where\\s+(.*))?$");
  private static final Pattern SELECT =
      Pattern.compile("(?is)^\\s*select\\s+(.*?)\\s+from\\s+(\\S+)(.*)$");
  private static final Pattern CONDITION = Pattern.compile(
      "(?i)([a-z0-9_.]+)\\s*(<>|!=|>=|<=|=|>|<|\\bnot\\s+like\\b|\\blike\\b|\\bnot\\s+in\\b|\\bin\\b|\\bis\\s+not\\s+null\\b|\\bis\\s+null\\b)\\s*(\\(\\s*\\?(?:\\s*,\\s*\\?)*\\s*\\)|\\?)?");

  private final Map<String, List<Map<String, Object>>> tables = new TreeMap<>();
  private final List<String> executed = new ArrayList<>();
  private Predicate<String> failOn = sql -> false;

  /** A datasource whose connections work over this database. */
  public DataSource dataSource() {
    return proxy(DataSource.class, (self, method, args) -> {
      if (method.getName().equals("getConnection")) {
        return connection();
      }
      return defaultValue(method);
    });
  }

  /** The rows stored on a table (the names of tables and columns are in lower case). */
  public List<Map<String, Object>> rows(String table) {
    return tables.getOrDefault(name(table), List.of());
  }

  /** All the sentences executed, in order. */
  public List<String> executed() {
    return executed;
  }

  /** Make fail with an SQLException the sentences that match the condition. */
  public InMemoryJdbc failOn(Predicate<String> condition) {
    this.failOn = condition;
    return this;
  }

  /** Remove all the data and the failures. */
  public void clear() {
    tables.clear();
    executed.clear();
    failOn = sql -> false;
  }

  /**
   * Compare two maps of values (as entity.toMap) allowing the dates with different offset for the
   * same instant.
   */
  public static boolean sameValues(Map<String, String> expected, Map<String, String> actual) {
    if (!expected.keySet().equals(actual.keySet())) {
      return false;
    }
    for (Map.Entry<String, String> entry : expected.entrySet()) {
      String other = actual.get(entry.getKey());
      if (!Objects.equals(entry.getValue(), other) && !sameInstant(entry.getValue(), other)) {
        return false;
      }
    }
    return true;
  }

  private static boolean sameInstant(String one, String other) {
    if (null == one || null == other) {
      return false;
    }
    try {
      return OffsetDateTime.parse(one).isEqual(OffsetDateTime.parse(other));
    } catch (DateTimeParseException ex) {
      return false;
    }
  }

  private Connection connection() {
    boolean[] state = new boolean[] {true, false}; // autocommit, closed
    return proxy(Connection.class, (self, method, args) -> {
      switch (method.getName()) {
        case "prepareStatement":
          return statement((String) args[0]);
        case "getMetaData":
          return metadata();
        case "getAutoCommit":
          return state[0];
        case "setAutoCommit":
          state[0] = (Boolean) args[0];
          return null;
        case "isClosed":
          return state[1];
        case "close":
          state[1] = true;
          return null;
        case "isValid":
          return true;
        default:
          return defaultValue(method);
      }
    });
  }

  private DatabaseMetaData metadata() {
    return proxy(DatabaseMetaData.class, (self, method, args) -> {
      switch (method.getName()) {
        case "getIdentifierQuoteString":
          return "\"";
        case "getDatabaseProductName":
          return "H2";
        case "getDriverName":
          return "In memory";
        case "getURL":
          return "jdbc:memory:test";
        default:
          return defaultValue(method);
      }
    });
  }

  private PreparedStatement statement(String sql) {
    Map<Integer, Object> params = new TreeMap<>();
    List<Map<Integer, Object>> batch = new ArrayList<>();
    return proxy(PreparedStatement.class, (self, method, args) -> {
      String name = method.getName();
      if (name.equals("setNull")) {
        params.put((Integer) args[0], null);
        return null;
      } else if (name.startsWith("set") && null != args && args.length >= 2
          && args[0] instanceof Integer index) {
        params.put(index, args[1]);
        return null;
      }
      switch (name) {
        case "clearParameters":
          params.clear();
          return null;
        case "addBatch":
          batch.add(new TreeMap<>(params));
          return null;
        case "executeBatch":
          int[] result = new int[batch.size()];
          for (int i = 0; i < batch.size(); i++) {
            result[i] = update(sql, batch.get(i));
          }
          batch.clear();
          return result;
        case "executeUpdate":
        case "executeLargeUpdate":
          int count = update(sql, params);
          return name.equals("executeLargeUpdate") ? (Object) (long) count : (Object) count;
        case "execute":
          if (sql.trim().toLowerCase(Locale.ROOT).startsWith("select")) {
            query(sql, params);
          } else {
            update(sql, params);
          }
          return true;
        case "executeQuery":
          return query(sql, params);
        default:
          return defaultValue(method);
      }
    });
  }

  private int update(String sql, Map<Integer, Object> params) throws SQLException {
    check(sql);
    String clean = clean(sql);
    Matcher insert = INSERT.matcher(clean);
    if (insert.matches()) {
      List<String> columns = split(insert.group(2));
      List<String> values = split(insert.group(3));
      if (columns.size() != values.size()) {
        throw new SQLException(
            "Insert with " + columns.size() + " columns and " + values.size() + " values: " + sql);
      }
      int[] index = new int[] {1};
      Map<String, Object> row = new LinkedHashMap<>();
      for (int i = 0; i < columns.size(); i++) {
        row.put(column(columns.get(i)), value(values.get(i), params, index));
      }
      tables.computeIfAbsent(name(insert.group(1)), _ -> new ArrayList<>()).add(row);
      return 1;
    }
    Matcher update = UPDATE.matcher(clean);
    if (update.matches()) {
      int[] index = new int[] {1};
      Map<String, Object> assigns = new LinkedHashMap<>();
      Map<String, String> increments = new LinkedHashMap<>();
      for (String part : split(update.group(2))) {
        int eq = part.indexOf('=');
        String col = column(part.substring(0, eq));
        String expression = part.substring(eq + 1).trim();
        if (expression.matches("(?i)[a-z0-9_.]+\\s*[+-]\\s*\\d+")) {
          increments.put(col, expression);
        } else {
          assigns.put(col, value(expression, params, index));
        }
      }
      List<Map<String, Object>> matched =
          filter(name(update.group(1)), update.group(3), params, index);
      for (Map<String, Object> row : matched) {
        increments.forEach((col, expression) -> {
          String[] parts = expression.split("[+-]");
          long delta = Long.parseLong(parts[1].trim()) * (expression.contains("-") ? -1 : 1);
          Object current = row.get(column(parts[0]));
          row.put(col, null == current ? null : toLong(current) + delta);
        });
        row.putAll(assigns);
      }
      return matched.size();
    }
    Matcher delete = DELETE.matcher(clean);
    if (delete.matches()) {
      List<Map<String, Object>> matched =
          filter(name(delete.group(1)), delete.group(2), params, new int[] {1});
      tables.getOrDefault(name(delete.group(1)), new ArrayList<>()).removeAll(matched);
      return matched.size();
    }
    throw new SQLException("Unsupported sentence on the in memory database: " + sql);
  }

  private ResultSet query(String sql, Map<Integer, Object> params) throws SQLException {
    check(sql);
    Matcher select = SELECT.matcher(clean(sql));
    if (!select.matches()) {
      throw new SQLException("Unsupported query on the in memory database: " + sql);
    }
    String rest = select.group(3);
    String where = null;
    Matcher whereMatcher = Pattern
        .compile("(?is)\\bwhere\\b(.*?)(\\border\\s+by\\b.*|\\bfor\\s+update\\b.*|\\blimit\\b.*|$)")
        .matcher(rest);
    if (whereMatcher.find()) {
      where = whereMatcher.group(1);
    }
    List<Map<String, Object>> matched = filter(name(select.group(2)), where, params, new int[] {1});
    List<String> fields = split(select.group(1));
    if (fields.size() == 1 && fields.get(0).toLowerCase(Locale.ROOT).startsWith("count(")) {
      Matcher alias = Pattern.compile("(?i)\\bas\\s+(\\S+)").matcher(fields.get(0));
      String label = alias.find() ? column(alias.group(1)) : "count";
      Map<String, Object> row = new LinkedHashMap<>();
      row.put(label, (long) matched.size());
      return resultSet(List.of(label), List.of(row));
    }
    List<String> labels = new ArrayList<>();
    for (String field : fields) {
      if (field.trim().equals("*")) {
        matched.stream().findFirst().ifPresent(row -> labels.addAll(row.keySet()));
      } else {
        Matcher alias = Pattern.compile("(?i)\\bas\\s+(\\S+)$").matcher(field.trim());
        labels.add(column(alias.find() ? alias.group(1) : field));
      }
    }
    return resultSet(labels,
        matched.stream().map(LinkedHashMap::new).map(r -> (Map<String, Object>) r).toList());
  }

  private ResultSet resultSet(List<String> labels, List<Map<String, Object>> rows) {
    int[] cursor = new int[] {-1};
    Object[] last = new Object[1];
    return proxy(ResultSet.class, (self, method, args) -> {
      String name = method.getName();
      switch (name) {
        case "next":
          cursor[0]++;
          return cursor[0] < rows.size();
        case "wasNull":
          return null == last[0];
        case "close":
        case "isClosed":
          return defaultValue(method);
        case "getMetaData":
          return proxy(ResultSetMetaData.class, (s2, m2, a2) -> {
            switch (m2.getName()) {
              case "getColumnCount":
                return labels.size();
              case "getColumnLabel":
              case "getColumnName":
                return labels.get((Integer) a2[0] - 1);
              default:
                return defaultValue(m2);
            }
          });
        case "findColumn":
          return labels.indexOf(column((String) args[0])) + 1;
        default:
          if (name.startsWith("get") && null != args && args.length >= 1) {
            Map<String, Object> row = rows.get(cursor[0]);
            String label =
                args[0] instanceof Integer index ? labels.get(index - 1) : column((String) args[0]);
            if (!row.containsKey(label)) {
              throw new SQLException("Column " + label + " not found on the result " + labels);
            }
            last[0] = row.get(label);
            Class<?> type = args.length > 1 && args[1] instanceof Class<?> clazz ? clazz
                : method.getReturnType();
            return convert(last[0], type);
          }
          return defaultValue(method);
      }
    });
  }

  private List<Map<String, Object>> filter(String table, String where, Map<Integer, Object> params,
      int[] index) {
    List<Map<String, Object>> rows = tables.getOrDefault(table, List.of());
    if (null == where || where.isBlank()) {
      return new ArrayList<>(rows);
    }
    List<Predicate<Map<String, Object>>> conditions = new ArrayList<>();
    Matcher matcher = CONDITION.matcher(where);
    while (matcher.find()) {
      int depth = depth(where, matcher.start());
      String col = column(matcher.group(1));
      String op = matcher.group(2).toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
      String holder = matcher.group(3);
      List<Object> values = new ArrayList<>();
      if (null != holder) {
        long count = holder.chars().filter(c -> c == '?').count();
        for (int i = 0; i < count; i++) {
          values.add(params.get(index[0]++));
        }
      } else if (!op.startsWith("is")) {
        continue;
      }
      if (depth > 0) {
        continue;
      }
      conditions.add(row -> matches(row.get(col), op, values));
    }
    return rows.stream().filter(row -> conditions.stream().allMatch(c -> c.test(row)))
        .collect(java.util.stream.Collectors.toCollection(ArrayList::new));
  }

  private static boolean matches(Object value, String op, List<Object> values) {
    switch (op) {
      case "is null":
        return null == value;
      case "is not null":
        return null != value;
      case "in":
        return values.stream().anyMatch(v -> compare(value, v) == 0);
      case "not in":
        return values.stream().noneMatch(v -> compare(value, v) == 0);
      case "like":
      case "not like":
        boolean like = null != value && null != values.get(0) && String.valueOf(value).matches(
            "(?s)" + Pattern.quote(String.valueOf(values.get(0))).replace("%", "\\E.*\\Q"));
        return op.equals("like") == like;
      default:
        if (null == value || null == values.get(0)) {
          return false;
        }
        int compare = compare(value, values.get(0));
        switch (op) {
          case "=":
            return compare == 0;
          case "<>":
          case "!=":
            return compare != 0;
          case ">":
            return compare > 0;
          case "<":
            return compare < 0;
          case ">=":
            return compare >= 0;
          case "<=":
            return compare <= 0;
          default:
            return true;
        }
    }
  }

  private static int compare(Object one, Object other) {
    if (null == one || null == other) {
      return null == one && null == other ? 0 : -1;
    }
    if (one instanceof Number || other instanceof Number) {
      try {
        return new BigDecimal(String.valueOf(one)).compareTo(new BigDecimal(String.valueOf(other)));
      } catch (NumberFormatException ex) {
        // compare as text
      }
    }
    if (one instanceof java.util.Date || other instanceof java.util.Date) {
      return Long.compare(toTimestamp(one).getTime(), toTimestamp(other).getTime());
    }
    return String.valueOf(one).compareTo(String.valueOf(other));
  }

  private static Object convert(Object value, Class<?> type) throws SQLException {
    if (type == boolean.class || type == Boolean.class) {
      return null == value ? (type == boolean.class ? false : null)
          : value instanceof Boolean b ? b
              : value instanceof Number n ? n.intValue() != 0
                  : Boolean.parseBoolean(String.valueOf(value));
    }
    if (type == int.class || type == Integer.class) {
      return null == value ? (type == int.class ? 0 : null) : (int) toLong(value);
    }
    if (type == long.class || type == Long.class) {
      return null == value ? (type == long.class ? 0L : null) : toLong(value);
    }
    if (type == short.class || type == Short.class) {
      return null == value ? (short) 0 : (short) toLong(value);
    }
    if (type == byte.class || type == Byte.class) {
      return null == value ? (byte) 0 : (byte) toLong(value);
    }
    if (type == double.class || type == Double.class) {
      return null == value ? 0.0 : new BigDecimal(String.valueOf(value)).doubleValue();
    }
    if (type == float.class || type == Float.class) {
      return null == value ? 0.0f : new BigDecimal(String.valueOf(value)).floatValue();
    }
    if (null == value) {
      return null;
    }
    if (type == String.class) {
      return value instanceof byte[] bytes ? new String(bytes) : String.valueOf(value);
    }
    if (type == BigDecimal.class) {
      return value instanceof BigDecimal bd ? bd : new BigDecimal(String.valueOf(value));
    }
    if (type == Timestamp.class) {
      return toTimestamp(value);
    }
    if (type == java.sql.Date.class) {
      return value instanceof java.sql.Date d ? d
          : value instanceof LocalDate ld ? java.sql.Date.valueOf(ld)
              : new java.sql.Date(toTimestamp(value).getTime());
    }
    if (type == java.sql.Time.class) {
      return value instanceof java.sql.Time t ? t : new java.sql.Time(toTimestamp(value).getTime());
    }
    if (type == byte[].class) {
      return value instanceof byte[] bytes ? bytes : String.valueOf(value).getBytes();
    }
    if (type == java.io.InputStream.class) {
      return new ByteArrayInputStream(
          value instanceof byte[] bytes ? bytes : String.valueOf(value).getBytes());
    }
    if (type == OffsetDateTime.class) {
      return value instanceof OffsetDateTime odt ? odt
          : toTimestamp(value).toInstant().atOffset(java.time.ZoneOffset.UTC);
    }
    if (type == LocalDateTime.class) {
      return value instanceof LocalDateTime ldt ? ldt : toTimestamp(value).toLocalDateTime();
    }
    if (type == LocalDate.class) {
      return value instanceof LocalDate ld ? ld
          : toTimestamp(value).toLocalDateTime().toLocalDate();
    }
    if (type.isInstance(value)) {
      return value;
    }
    throw new SQLException("Unable to convert " + value.getClass() + " into " + type);
  }

  private static Timestamp toTimestamp(Object value) {
    if (value instanceof Timestamp ts) {
      return ts;
    } else if (value instanceof java.util.Date date) {
      return new Timestamp(date.getTime());
    } else if (value instanceof OffsetDateTime odt) {
      return Timestamp.from(odt.toInstant());
    } else if (value instanceof LocalDateTime ldt) {
      return Timestamp.valueOf(ldt);
    } else if (value instanceof LocalDate ld) {
      return Timestamp.valueOf(ld.atStartOfDay());
    } else if (value instanceof Instant instant) {
      return Timestamp.from(instant);
    } else if (value instanceof Number n) {
      return new Timestamp(n.longValue());
    }
    return Timestamp.valueOf(String.valueOf(value));
  }

  private static long toLong(Object value) {
    return value instanceof Number n ? n.longValue()
        : value instanceof Boolean b ? (b ? 1 : 0)
            : new BigDecimal(String.valueOf(value)).longValue();
  }

  private Object value(String expression, Map<Integer, Object> params, int[] index) {
    String trimmed = expression.trim();
    if (trimmed.equals("?")) {
      return params.get(index[0]++);
    } else if (trimmed.equalsIgnoreCase("null")) {
      return null;
    } else if (trimmed.startsWith("'") && trimmed.endsWith("'")) {
      return trimmed.substring(1, trimmed.length() - 1).replace("''", "'");
    } else if (trimmed.equalsIgnoreCase("true") || trimmed.equalsIgnoreCase("false")) {
      return Boolean.parseBoolean(trimmed);
    }
    try {
      return new BigDecimal(trimmed);
    } catch (NumberFormatException ex) {
      return trimmed;
    }
  }

  private void check(String sql) throws SQLException {
    executed.add(sql);
    if (failOn.test(sql)) {
      throw new SQLException("Forced failure on " + sql);
    }
  }

  private static int depth(String text, int position) {
    int depth = 0;
    boolean literal = false;
    for (int i = 0; i < position; i++) {
      char c = text.charAt(i);
      if (c == '\'') {
        literal = !literal;
      } else if (!literal && c == '(') {
        depth++;
      } else if (!literal && c == ')') {
        depth--;
      }
    }
    return depth;
  }

  /** Split by the commas out of parentheses and literals. */
  private static List<String> split(String text) {
    List<String> parts = new ArrayList<>();
    int depth = 0;
    boolean literal = false;
    StringBuilder current = new StringBuilder();
    for (char c : text.toCharArray()) {
      if (c == '\'') {
        literal = !literal;
      } else if (!literal && c == '(') {
        depth++;
      } else if (!literal && c == ')') {
        depth--;
      } else if (!literal && depth == 0 && c == ',') {
        parts.add(current.toString().trim());
        current.setLength(0);
        continue;
      }
      current.append(c);
    }
    if (!current.toString().isBlank()) {
      parts.add(current.toString().trim());
    }
    return parts;
  }

  private static String clean(String sql) {
    return sql.replace("\"", "").replace("`", "").replace("[", "").replace("]", "").trim();
  }

  private static String name(String table) {
    return clean(table).toLowerCase(Locale.ROOT);
  }

  private static String column(String field) {
    String clean = clean(field).toLowerCase(Locale.ROOT);
    int dot = clean.lastIndexOf('.');
    return dot == -1 ? clean : clean.substring(dot + 1);
  }

  private static Object defaultValue(Method method) {
    Class<?> type = method.getReturnType();
    if (type == boolean.class) {
      return false;
    } else if (type == int.class || type == long.class || type == short.class
        || type == byte.class) {
      return type == long.class ? (Object) 0L : (Object) 0;
    } else if (type == double.class || type == float.class) {
      return type == float.class ? (Object) 0.0f : (Object) 0.0;
    } else if (type == String.class && method.getName().equals("toString")) {
      return "in-memory-jdbc";
    }
    return null;
  }

  @SuppressWarnings("unchecked")
  private static <T> T proxy(Class<T> type, InvocationHandler handler) {
    return (T) Proxy.newProxyInstance(InMemoryJdbc.class.getClassLoader(), new Class<?>[] {type},
        (self, method, args) -> {
          if (method.getName().equals("hashCode")) {
            return System.identityHashCode(self);
          } else if (method.getName().equals("equals")) {
            return self == args[0];
          } else if (method.getName().equals("unwrap")) {
            return null;
          } else if (method.getName().equals("isWrapperFor")) {
            return false;
          }
          return handler.invoke(self, method, args);
        });
  }
}
